// Shape of exports/<slug>/scene-data.json. Generated by `npm run reel -- build`, editable by hand.

export type Line = {
  /** Text shown on screen. Wrap words in *stars* to highlight them. */
  text: string;
  /** Seconds after the scene starts when this line appears. */
  at: number;
  size?: 'xl' | 'lg' | 'md' | 'sm';
};

export type SceneType = 'hook' | 'message' | 'tip' | 'reinforce' | 'closing';

export type Scene = {
  id: string;
  type: SceneType;
  kicker: string;
  lines: Line[];
  /** Checklist items (tip scene). */
  items?: {text: string; at: number}[];
  /** Big figure for the tip scene, e.g. {value: "15", unit: "minit"}. */
  figure?: {value: string; unit: string} | null;
  /** Narration for this scene (used for the voiceover script and timing). */
  narration: string;
  durationInFrames: number;
  showPortrait?: boolean;
};

export type CaptionCue = {startMs: number; endMs: number; text: string};

export type Media = {
  portrait: null | {kind: 'image' | 'video'; src: string; focus: string};
  voiceover: null | {src: string; durationSec: number};
  music: null | {src: string; volume: number; credit: string};
};

export type SceneData = {
  version: 1;
  slug: string;
  topic: string;
  fps: number;
  width: number;
  height: number;
  transitionFrames: number;
  seriesLabel: string;
  signoff: string;
  media: Media;
  captions: {
    mode: 'none' | 'provided-srt' | 'estimated-from-script';
    burnIn: boolean;
    cues: CaptionCue[];
  };
  cover: {title: string; kicker: string; noPortrait?: boolean};
  scenes: Scene[];
};
